// hmd-mp4-shortcut.js
// Helper to short-circuit HMD preview by using preprocessed left.mp4 (only
// the left eye is generated by default — right eye is skipped to save ~50%
// preprocessing time, since the left eye alone is enough to know what the
// video is about). Falls back gracefully when the MP4 isn't ready.
//
// Usage:
//   import { tryOpenHmdMp4 } from '/static/hmd/hmd-mp4-shortcut.js';
//   const r = await tryOpenHmdMp4({
//     folder,
//     leftVideo,           // pre-existing <video> element (rightVideo optional)
//     onProgress: (stage, pct) => { ... },
//   });
//   if (r) {
//     // r.mode === 'mp4'
//     // r.leftUrl — direct URL to MP4
//     // r.durationSec
//     // r.bindEvents({ onPlay, onPause, onSeek, onTimeUpdate })
//   } else {
//     // fall back to WebCodecs path; preprocessing kicked off in background
//   }

const STATUS_PATH = '/api/hmd/process-status';
const MP4_PATH = '/api/hmd/mp4';
const PROCESS_START = '/api/hmd/process';

async function fetchStatus(folder) {
  try {
    const r = await fetch(STATUS_PATH + '?folder=' + encodeURIComponent(folder));
    if (!r.ok) return { status: 'unknown' };
    return await r.json();
  } catch {
    return { status: 'unknown' };
  }
}

async function kickoffPreprocess(folder) {
  try {
    await fetch(PROCESS_START, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ folder: folder }),
    });
  } catch { /* ignore */ }
}

function mp4Url(folder, eye) {
  // Normalize path separators to forward slashes for URL safety
  const normalizedFolder = (folder || '').replace(/\\/g, '/');
  return MP4_PATH + '?folder=' + encodeURIComponent(normalizedFolder) + '&eye=' + eye;
}

/**
 * Try to open a HMD session via preprocessed MP4.
 * Returns a session object on success, or null if MP4 not ready.
 *
 * @param {Object} opts
 * @param {string} opts.folder
 * @param {HTMLVideoElement} [opts.leftVideo]
 * @param {HTMLVideoElement} [opts.rightVideo]
 * @param {Function} [opts.onProgress] (stage, pct)
 * @returns {Promise<?Object>}
 */
export async function tryOpenHmdMp4(opts) {
  const { folder, leftVideo, rightVideo = null, onProgress = () => {} } = opts;
  if (!folder) return null;

  onProgress('check', 0);
  const status = await fetchStatus(folder);

  if (status.status === 'done') {
    onProgress('mp4', 100);
    return await attachMp4Session({ folder, leftVideo, rightVideo, status });
  }

  if (status.status === 'processing' || status.status === 'starting') {
    // Poll until done
    onProgress('waiting-mp4', 0);
    const start = Date.now();
    const TIMEOUT_MS = 5 * 60 * 1000;  // 5 min cap
    let pct = 0;
    while (Date.now() - start < TIMEOUT_MS) {
      await new Promise(r => setTimeout(r, 1000));
      const s = await fetchStatus(folder);
      if (s.status === 'done') {
        onProgress('mp4', 100);
        return await attachMp4Session({ folder, leftVideo, rightVideo, status: s });
      }
      if (s.status === 'error') {
        onProgress('mp4-error', 0);
        // fall through to kick off + return null
        break;
      }
      pct = s.progress || 0;
      onProgress('waiting-mp4', pct);
    }
    // timeout or error: kick off fresh + fall through
  }

  // Not ready → kick off preprocessing in background, return null so caller
  // can fall back to WebCodecs path for the current session.
  onProgress('kickoff-preprocess', 0);
  kickoffPreprocess(folder);
  return null;
}

async function attachMp4Session({ folder, leftVideo, rightVideo, status }) {
  const leftUrl = mp4Url(folder, 'left');
  const rightUrl = rightVideo ? mp4Url(folder, 'right') : null;

  if (leftVideo) {
    leftVideo.src = leftUrl;
    leftVideo.preload = 'auto';
    leftVideo.muted = true;   // autoplay-safe
    leftVideo.playsInline = true;
    leftVideo.load();
  }
  if (rightVideo && rightUrl) {
    rightVideo.src = rightUrl;
    rightVideo.preload = 'auto';
    rightVideo.muted = true;
    rightVideo.playsInline = true;
    rightVideo.load();
  }

  // Wait for the (left) video to know its duration
  const durationSec = (status && status.duration_sec) || 0;
  if (!durationSec) {
    const vid = leftVideo || rightVideo;
    if (vid) {
      await new Promise((resolve) => {
        if (vid.readyState >= 1 && isFinite(vid.duration) && vid.duration > 0) {
          resolve();
        } else {
          const onMeta = () => { vid.removeEventListener('loadedmetadata', onMeta); resolve(); };
          vid.addEventListener('loadedmetadata', onMeta);
          setTimeout(resolve, 3000);
        }
      });
    }
  }

  return {
    mode: 'mp4',
    folder,
    leftUrl,
    rightUrl,           // null when only left was generated
    durationSec: durationSec || (leftVideo ? leftVideo.duration : 0),
    leftVideo,
    rightVideo,
    status,

    // Sync helper: bind events so caller can hook up its UI controls
    bindEvents({ onPlay, onPause, onSeek, onTimeUpdate, onEnded } = {}) {
      const lv = leftVideo, rv = rightVideo;
      if (!lv) return;

      // If both videos present, sync them (left is master).
      if (rv) {
        let syncing = false;
        const syncRightToLeft = () => {
          if (syncing) return;
          if (Math.abs(rv.currentTime - lv.currentTime) > 0.1) {
            syncing = true;
            rv.currentTime = lv.currentTime;
            setTimeout(() => { syncing = false; }, 50);
          }
        };
        const syncLeftToRight = () => {
          if (syncing) return;
          if (Math.abs(lv.currentTime - rv.currentTime) > 0.1) {
            syncing = true;
            lv.currentTime = rv.currentTime;
            setTimeout(() => { syncing = false; }, 50);
          }
        };
        lv.addEventListener('seeked', syncRightToLeft);
        rv.addEventListener('seeked', syncLeftToRight);
        lv.addEventListener('play', () => { rv.play().catch(() => {}); if (onPlay) onPlay(); });
        lv.addEventListener('pause', () => { rv.pause(); if (onPause) onPause(); });
        rv.addEventListener('play', () => { lv.play().catch(() => {}); if (onPlay) onPlay(); });
        rv.addEventListener('pause', () => { lv.pause(); if (onPause) onPause(); });
      } else {
        // Single-video mode (left only)
        lv.addEventListener('play', () => { if (onPlay) onPlay(); });
        lv.addEventListener('pause', () => { if (onPause) onPause(); });
      }

      const tuHandler = () => {
        if (onTimeUpdate) onTimeUpdate(lv.currentTime, rv ? rv.currentTime : lv.currentTime);
      };
      lv.addEventListener('timeupdate', tuHandler);

      const endHandler = () => {
        if (onEnded) onEnded();
      };
      lv.addEventListener('ended', endHandler);
    },

    // Control methods (left-video-only or both)
    play() {
      if (leftVideo) leftVideo.play().catch(() => {});
      if (rightVideo) rightVideo.play().catch(() => {});
    },
    pause() {
      if (leftVideo) leftVideo.pause();
      if (rightVideo) rightVideo.pause();
    },
    toggle() {
      const playing = leftVideo && !leftVideo.paused;
      if (playing) this.pause(); else this.play();
      return !playing;
    },
    seek(sec) {
      if (leftVideo) leftVideo.currentTime = sec;
      if (rightVideo) rightVideo.currentTime = sec;
    },
    seekDelta(deltaSec) {
      if (leftVideo) leftVideo.currentTime = Math.max(0, leftVideo.currentTime + deltaSec);
      if (rightVideo) rightVideo.currentTime = Math.max(0, rightVideo.currentTime + deltaSec);
    },
    close() {
      if (leftVideo) { leftVideo.pause(); leftVideo.removeAttribute('src'); leftVideo.load(); }
      if (rightVideo) { rightVideo.pause(); rightVideo.removeAttribute('src'); rightVideo.load(); }
    },
    getCurrentTime() { return leftVideo ? leftVideo.currentTime : 0; },
    getDuration() { return leftVideo ? leftVideo.duration : 0; },
  };
}
